UPDATE lessons SET title='Year 3, Week 37, Lesson 2: Sorting and analysing information', data=json_patch(data,'{"child_mission":"Sorting information into categories helps find patterns and gaps. Facts can be checked in sources, while opinions are what people think or feel. Comparing sources shows where they agree and where they differ.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same HSIE idea to a new place or source, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nSort into fact or opinion: the library opened in 1962; the old library was friendlier; the council paid for a new roof.\n\nFEEDBACK\nFacts: opened in 1962; council paid for a new roof. Opinion: the old library was friendlier.\n\nWATCH FOR\nTreating a strong opinion as proven fact weakens the conclusion of an inquiry.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nSort your notes into three categories. Mark each fact or opinion, write one pattern and one gap, and compare two sources: where do they agree and differ?\n\nWrite a short reflection naming one source or idea you corrected and why.","interactive_activities":null,"learning_area":"HSIE","learning_intention":"Sorting information into categories helps find patterns and gaps. Facts can be checked in sources, while opinions are what people think or feel. Comparing sources shows where they agree and where they differ.","lesson_number":2,"lesson_role":"Apply and respond","materials":["Paper or typed answer space","Pencil","Optional: local map, photo or interview notes"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["HS2-HIS-01"],"parent_notes":"Parent: Marking guidance for the independent task: Sort your notes into three categories. Mark each fact or opinion, write one pattern and one gap, and compare two sources: where do they agree and differ? Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: original example using sort on new material; names a specific word, source or choice and explains its effect.\n\nParent: Written model 2: Sample error: Treating a strong opinion as proven fact weakens the conclusion of an inquiry.. Correction: Facts: opened in 1962; council paid for a new roof.. Why it helps the audience is stated.\n\nParent: Likely misconception: Treating a strong opinion as proven fact weakens the conclusion of an inquiry. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating sort on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with sort, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Accept original work about sort with a specific supporting detail. Reject copied model wording with no new material. / Accept a misconception, a correction, and a purpose-linked reason for sort. Reject corrections that do not change the inaccurate idea..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for sort. The other choices miss a key step or use a common mistake.","options":["Facts: opened in 1962; council paid for a new roof","Treating a strong opinion as proven fact weakens the conclusion of an inquiry","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Sort into fact or opinion: the library opened in 1962; the old library was friendlier; the council paid for a new roof. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"This is the misconception to avoid for sort; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Sorting information into categories helps find patterns and gaps","Facts: opened in 1962; council paid for a new roof","Careful use of pattern and explain why it matters with clear evidence","Treating a strong opinion as proven fact weakens the conclusion of an inquiry"],"question":"Which statement is a common mistake when working with sort?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and a named pattern and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Treating a strong opinion as proven fact weakens the conclusion of an inquiry","Name pattern and explain why it matters only, without linking it to sort","Apply sort to new material and name the pattern and explain why it matters used","Repeat the worked example wording with no new evidence"],"question":"Which response best applies sort with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"The stronger choice uses sources, places or historical/geographic evidence appropriately for this lesson on sort. The other choices miss a key step or use a common mistake.","options":["Copy a classmate’s sentence with no local detail","Treating a strong opinion as proven fact weakens the conclusion of an inquiry","Facts: opened in 1962; council paid for a new roof","Make a bigger claim without naming any source or place detail"],"question":"Which response best uses sources, places or historical/geographic evidence for sort?","type":"multiple_choice"},{"correct_index":2,"explanation":"Strong answers name specific evidence and what it shows. The other choices miss a key step or use a common mistake.","options":["Copy a classmate’s sentence with no local detail","Treating a strong opinion as proven fact weakens the conclusion of an inquiry","Name a specific source or place detail and say what it shows about sort","Make a bigger claim without naming any source or place detail"],"question":"Which evidence move best supports a claim about sort?","type":"multiple_choice"},{"correct_index":0,"explanation":"The stronger choice matches the taught idea (Sorting information into categories helps find patterns and gaps.) with concrete detail. The other choices miss a key step or use a common mistake.","options":["Example: for the library inquiry, notes are sorted into buildings, services and people","Treating a strong opinion as proven fact weakens the conclusion of an inquiry","Make a bigger claim without naming any source or place detail","Copy a classmate’s sentence with no local detail"],"question":"Which choice best applies this lesson idea about sort?","type":"multiple_choice"},{"correct_index":0,"explanation":"Accuracy means checking evidence and honouring limits or protocols. The other choices miss a key step or use a common mistake.","options":["Check facts, acknowledge limits of the evidence, and avoid inventing details","Invent missing details to make the answer sound complete","Ignore safety or cultural protocols to finish faster","Treat every claim as equally reliable without checking a source or cue"],"question":"Which action keeps sources, places or historical/geographic evidence accurate for sort?","type":"multiple_choice"},{"correct_index":1,"explanation":"Independence requires a new example that still uses the taught skill. The other choices miss a key step or use a common mistake.","options":["Name pattern and explain why it matters only, with no linked example","Sort your notes into three categories","Retype the worked example with no new example","Treating a strong opinion as proven fact weakens the conclusion of an inquiry"],"question":"Which independent response best applies sort to new material?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept original work about sort with a specific supporting detail. Reject copied model wording with no new material.","question":"Produce a fresh example demonstrating sort on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Sample: original example using sort on new material; names a specific word, source or choice and explains its effect.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception, a correction, and a purpose-linked reason for sort. Reject corrections that do not change the inaccurate idea.","question":"Name one likely error with sort, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Sample error: Treating a strong opinion as proven fact weakens the conclusion of an inquiry.. Correction: Facts: opened in 1962; council paid for a new roof.. Why it helps the audience is stated.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-hsie-y3-w37-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA HSIE alignment using catalogue outcome codes (HS2-*); content-point mapping and local First Nations protocols remain pending human review.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise sort.","Read the mission before you start mapping or using sources.","Keep the place, people or source you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the source or place detail that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore sources or respectful practice.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread names, places, dates and sequence.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact source detail or place feature before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key evidence.","Say what each source or place detail shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or use of sources, not only how neat the poster looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, person or source that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new sources or places."]},"subject":"Historical and Geographical Inquiry","success_criteria":["I can use sort with a specific example from this lesson.","I can identify pattern and explain why it matters.","I can practise fact independently on a new prompt.","I can notice opinion needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Sorting information into categories helps find patterns and gaps.","options":["Sorting information into categories helps find patterns and gaps","A claim unrelated to the source or place","An answer copied without understanding","A guess with no evidence"],"question":"Which choice best applies this lesson idea about sort with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: for the library inquiry, notes are sorted into buildings, services and people. A pattern appears: more services were added after 2000. Fact: \"The library opened a children''s section in 1998.\" Opinion: \"The old library was nicer.\"\n\nTRY FIRST\nSort into fact or opinion: the library opened in 1962; the old library was friendlier; the council paid for a new roof.\n\nFEEDBACK\nFacts: opened in 1962; council paid for a new roof. Opinion: the old library was friendlier.","explain":"Sorting information into categories helps find patterns and gaps. Facts can be checked in sources, while opinions are what people think or feel. Comparing sources shows where they agree and where they differ.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Treating a strong opinion as proven fact weakens the conclusion of an inquiry. Correct the claim or use of sources, not just the neatness of the poster.","title":"Understand and model","visual":[{"alt":"Fact and opinion.","caption":"Facts can be traced to sources.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Fact</text><text x=\"28\" y=\"78\">opened in 1962</text><text x=\"358\" y=\"42\">Opinion</text><text x=\"358\" y=\"78\">the old one was friendlier</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which source or place detail matters most.","who":"pip"},{"text":"Name the sources, map features or community examples that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Example: for the library inquiry, notes are sorted into buildings, services and people. A pattern appears: more services Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which source or place detail matters most.\nJuno: Name the sources, map features or community examples that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Example: for the library inquiry, notes are sorted into buildings, services and people. A pattern appears: more services Then write your own evidence."}}]},{"check":{"correct_index":2,"explanation":"Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim.","options":["A guess with no evidence","A claim unrelated to the source or place","Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim","An answer copied without understanding"],"question":"Which choice best applies this lesson idea about sort with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nExample: for the library inquiry, notes are sorted into buildings, services and people. A pattern appears: more services were added after 2000. Fact: \"The library opened a children''s section in 1998.\" Opinion: \"The old library was nicer.\" Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the HSIE idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show HSIE thinking. Correct the claim or use of sources, not just the neatness of the poster.","title":"Show the evidence","visual":[{"alt":"Patterns and gaps.","caption":"Gaps show what to ask next.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Pattern</text><text x=\"28\" y=\"78\">more services after 2000</text><text x=\"358\" y=\"42\">Gap</text><text x=\"358\" y=\"78\">no dates for the roof</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally incorrect claim as a comparison.","options":["Use an intentionally incorrect claim as a comparison","A claim unrelated to the source or place","An answer copied without understanding","A guess with no evidence"],"question":"Which choice best applies this lesson idea about sort with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nTreating a strong opinion as proven fact weakens the conclusion of an inquiry. Here is a more productive model: Example: for the library inquiry, notes are sorted into buildings, services and people. A pattern appears: more services were added after 2000. Fact: \"The library opened a children''s section in 1998.\" Opinion: \"The old library was nicer.\"\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nFacts: opened in 1962; council paid for a new roof. Opinion: the old library was friendlier.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific HSIE error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. Treating a strong opinion as proven fact weakens the conclusion of an inquiry. Correct the claim or use of sources, not just the neatness of the poster.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example.","options":["A claim unrelated to the source or place","An answer copied without understanding","A guess with no evidence","Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example"],"question":"Which choice best applies this lesson idea about sort with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nSorting information into categories helps find patterns and gaps. Facts can be checked in sources, while opinions are what people think or feel. Comparing sources shows where they agree and where they differ. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same HSIE idea as the model, but contain different evidence.","explain":"Use the same HSIE idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on sources, places and respectful community knowledge, rather than guessing from a single picture. Keep every claim linked to evidence.\n\nHOW TO WORK\nRead the worked example and name the sources, map features or community examples that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a detail is uncertain, identify what source you would need next. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or use of sources, not just the neatness of the poster.","title":"Transfer to a new inquiry"}],"title":"Year 3, Week 37, Lesson 2: Sorting and analysing information","unit_number":8,"unit_title":"Inquiry project","week":37,"week_in_unit":2,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nExample: for the library inquiry, notes are sorted into buildings, services and people. A pattern appears: more services were added after 2000. Fact: \"The library opened a children''s section in 1998.\" Opinion: \"The old library was nicer.\"\n\nWrite what makes this example accurate, naming the sources, places or community details used.","worked_visuals":[{"alt":"Fact and opinion.","caption":"Facts can be traced to sources.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Fact</text><text x=\"28\" y=\"78\">opened in 1962</text><text x=\"358\" y=\"42\">Opinion</text><text x=\"358\" y=\"78\">the old one was friendlier</text></g></svg>"},{"alt":"Patterns and gaps.","caption":"Gaps show what to ask next.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Pattern</text><text x=\"28\" y=\"78\">more services after 2000</text><text x=\"358\" y=\"42\">Gap</text><text x=\"358\" y=\"78\">no dates for the roof</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-hsie-y3-w37-l2' AND family_id IS NULL;
